// Shared branding constants + PDF letterhead helper, used by every
// generated document (activity reports, offer letters, invoices).
// Keeping this in one place means the logo, colours, and company
// identity block only ever need to be edited in one file.

export const BRAND = {
  companyLegal: "SUIBING LIMITED",
  companyTrade: "trading as Suibing IT Services",
  rc: "RC 9801555",
  tin: "TIN: 2621958799448",
  address: "Makwalla Junction, Garko LGA, Kano State, Nigeria",
  email: "suibing15@gmail.com",
  phone: "+234 706 859 5598",
  navy: [27, 42, 74] as [number, number, number],
  navy2: [46, 67, 114] as [number, number, number],
  ink2: [69, 80, 106] as [number, number, number],
  muted: [107, 118, 136] as [number, number, number],
};

// Base64 PNG of the SB monogram logo — embedded directly so generated
// PDFs never depend on an external file existing at deploy time.
export const LOGO_PNG_BASE64 =
  "data:image/png;base64,";

// Draws the standard letterhead (logo + company name + contact line +
// divider) at the top of a jsPDF document. Returns the Y position to
// continue drawing content from.
export function drawLetterhead(doc: any, title: string, subtitle?: string) {
  const W = doc.internal.pageSize.getWidth();
  const { navy, ink2, muted } = BRAND;

  try {
    doc.addImage(LOGO_PNG_BASE64, "PNG", W / 2 - 9, 10, 18, 18);
  } catch {}

  doc.setFont("helvetica", "bold");
  doc.setFontSize(15);
  doc.setTextColor(...navy);
  doc.text(BRAND.companyLegal, W / 2, 34, { align: "center" });

  doc.setFont("helvetica", "normal");
  doc.setFontSize(9);
  doc.setTextColor(...muted);
  doc.text(`${BRAND.rc} · ${BRAND.companyTrade}`, W / 2, 39.5, { align: "center" });
  doc.text(BRAND.address, W / 2, 44, { align: "center" });
  doc.text(`${BRAND.email} · ${BRAND.phone}`, W / 2, 48.5, { align: "center" });

  doc.setDrawColor(...navy);
  doc.setLineWidth(0.5);
  doc.line(18, 54, W - 18, 54);

  doc.setFont("helvetica", "bold");
  doc.setFontSize(16);
  doc.setTextColor(...navy);
  doc.text(title, W / 2, 64, { align: "center" });

  let y = 64;
  if (subtitle) {
    doc.setFont("helvetica", "italic");
    doc.setFontSize(10.5);
    doc.setTextColor(...ink2);
    doc.text(subtitle, W / 2, 70, { align: "center" });
    y = 70;
  }

  return y + 10;
}

// Draws a consistent footer (page number + confidentiality line +
// identity block) at the bottom of the current page.
export function drawFooter(doc: any, pageLabel?: string) {
  const W = doc.internal.pageSize.getWidth();
  const H = doc.internal.pageSize.getHeight();
  const { muted } = BRAND;
  doc.setDrawColor(224, 228, 236);
  doc.setLineWidth(0.3);
  doc.line(18, H - 18, W - 18, H - 18);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(7.5);
  doc.setTextColor(...muted);
  doc.text(`${BRAND.companyLegal} (${BRAND.rc}) · ${BRAND.companyTrade}`, 18, H - 12);
  if (pageLabel) doc.text(pageLabel, W - 18, H - 12, { align: "right" });
}
